-- 158: Québec Law 25 as a compliance framework.
-- "Law 25" (SQ 2021, c. 25, formerly Bill 64) modernised Québec's Act respecting the
-- protection of personal information in the private sector (CQLR c. P-39.1); its
-- provisions came into force in three stages (22 September 2022, 2023 and 2024).
-- 60 requirements in 11 domains, each phrased as an assessment question and carrying
-- the section of the Act it comes from (guidance column). Requirement definitions only —
-- every organisation records its own assessment. Stored the same way as PIPEDA
-- (COMPLIANCE_ONLY, one "Requirement" level, the standard status list).
-- Safe to run more than once.

BEGIN;

INSERT INTO bayanat.gov_compliance_frameworks (name, code, version, description, regulation_group_code, is_applicable_indicator, assessment_mode)
VALUES (
  'Québec Law 25', 'QC_LAW25', '2024',
  $t$Québec — Act respecting the protection of personal information in the private sector (CQLR c. P-39.1) as amended by Law 25 (SQ 2021, c. 25). Applies to enterprises that collect, hold, use or communicate personal information in the course of carrying on an enterprise in Québec. Overseen by the Commission d'accès à l'information (CAI). Administrative monetary penalties up to CA$10,000,000 or 2% of worldwide turnover; penal fines up to CA$25,000,000 or 4% of worldwide turnover.$t$,
  'INTERNATIONAL_STANDARDS', true, 'COMPLIANCE_ONLY'
)
ON CONFLICT (code) DO NOTHING;

INSERT INTO bayanat.gov_compliance_requirements
  (framework_id, req_code, domain, domain_en, domain_code, standard, standard_code, req_text, question_en, guidance,
   maturity_level, compliance_or_maturity, sort_order)
SELECT f.framework_id, v.req_code, v.domain, v.domain, v.domain_code, v.standard, v.standard, v.req_text, v.req_text, v.guidance,
       '0', 'Compliance', v.sort_order
FROM bayanat.gov_compliance_frameworks f
