WHERE f.code = 'QC_LAW25'
ON CONFLICT (framework_id, req_code) DO NOTHING;

-- Same level and status configuration as the other compliance-only frameworks (copied from PIPEDA).
INSERT INTO bayanat.gov_compliance_level_config (framework_id, level_num, name, color_hex, description)
SELECT n.framework_id, c.level_num, c.name, c.color_hex, c.description
FROM bayanat.gov_compliance_level_config c
JOIN bayanat.gov_compliance_frameworks p ON p.framework_id = c.framework_id AND p.code = 'PIPEDA'
CROSS JOIN bayanat.gov_compliance_frameworks n
WHERE n.code = 'QC_LAW25'
  AND NOT EXISTS (SELECT 1 FROM bayanat.gov_compliance_level_config x WHERE x.framework_id = n.framework_id);

INSERT INTO bayanat.compliance_config_items (framework_id, config_group, code, label, label_ar, color_hex, sort_order)
SELECT n.framework_id, c.config_group, c.code, c.label, c.label_ar, c.color_hex, c.sort_order
FROM bayanat.compliance_config_items c
JOIN bayanat.gov_compliance_frameworks p ON p.framework_id = c.framework_id AND p.code = 'PIPEDA'
CROSS JOIN bayanat.gov_compliance_frameworks n
WHERE n.code = 'QC_LAW25'
  AND NOT EXISTS (SELECT 1 FROM bayanat.compliance_config_items x WHERE x.framework_id = n.framework_id);

COMMIT;
